// Generated from src/registry/sources/control-ui/recipes/kbd.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const kbdKnobs = [
  "--cui-kbd-radius",
  "--cui-kbd-background",
  "--cui-kbd-foreground",
  "--cui-kbd-border-color",
  "--cui-kbd-shadow",
] as const;
export type KbdKnobStyle = Partial<Record<(typeof kbdKnobs)[number], string>>;

@layer components {
  :where([data-control-family="kbd"][data-slot="root"]) {
    --cui-kbd-radius: var(--radius-control);
    --cui-kbd-background: oklch(from var(--card) l c h / 0.6);
    --cui-kbd-foreground: var(--muted-foreground);
    --cui-kbd-border-color: var(--border);
    --cui-kbd-shadow: var(--shadow-sm);
    border-radius: var(--cui-kbd-radius);
    background: var(--cui-kbd-background);
    box-shadow:
      inset 0 0 0 1px var(--cui-kbd-border-color),
      var(--cui-kbd-shadow);
    color: var(--cui-kbd-foreground);
    font-size: var(--text-micro);
    font-family: var(--font-sans);
    font-weight: var(--font-weight-medium);
  }
}

@property --cui-kbd-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-kbd-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-shadow {
  syntax: "*";
  inherits: true;
}

import type { ComponentProps, CSSProperties } from "react";

import type { KbdKnobStyle } from "@/components/control-ui/knob-contracts/kbd-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type KbdProps = Omit<ComponentProps<"kbd">, "style"> & { style?: CSSProperties & KbdKnobStyle };

export function Kbd({ className, ...props }: KbdProps) {
  return (
    <kbd
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="root"
      className={cn("inline-flex h-5 min-w-5 select-none items-center justify-center gap-1 px-1.5", className)}
      {...props}
    />
  );
}

export function KbdGroup({ className, ...props }: ComponentProps<"span"> & { style?: CSSProperties & KbdKnobStyle }) {
  return (
    <span
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="group"
      className={cn("inline-flex items-center gap-1", className)}
      {...props}
    />
  );
}
